/* Folder workspaces and explicit, focused editors. No document is run to edit it. */
(() => {
  const $=s=>document.querySelector(s), panel=$('.central-grid'), workspace=$('#workspace');
  const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
  const api=async(path,data)=>{const r=await fetch('/api/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.detail||'The workspace could not complete this action.');return d;};
  const fail=error=>VisionWorkspace.notify(error);
  const button=(label,action,parent)=>{const n=el('button','workspace-button',label);n.type='button';n.onclick=()=>Promise.resolve().then(action).catch(fail);parent.append(n);return n;};
  let project=null,activeFile=null,editorVersion=0,treeRelative='',normalLayout=null,treeHost=null,clipboardReady=false;
  const editor={dirty:false,async mayLeave(){if(!this.dirty)return true;const yes=await VisionShell.modal('Discard unsaved edits?',{text:'Your file has not been changed. Discard these edits to continue.',confirm:'Discard edits',danger:true});if(yes)this.dirty=false;return !!yes;}};
  window.VisionEditor=editor;
  function focus(){if(!workspace.classList.contains('editing')){const style=getComputedStyle(document.documentElement);normalLayout=Object.fromEntries(['--logs-width','--chat-width','--terminal-height'].map(name=>[name,style.getPropertyValue(name)]));}workspace.classList.add('editing');window.dispatchEvent(new Event('resize'));}
  function unfocus(){workspace.classList.remove('editing');if(normalLayout){for(const [name,value] of Object.entries(normalLayout))document.documentElement.style.setProperty(name,value);normalLayout=null;}activeFile=null;editorVersion++;window.dispatchEvent(new Event('resize'));}
  async function leaveEdit(){if(!workspace.classList.contains('editing'))return true;if(!await editor.mayLeave())return false;const current=VisionUI.currentPreview();unfocus();VisionUI.choosePreview(current.file?.kind==='project'?'grid':current.id);return true;}
  window.addEventListener('vision:preview-selected',()=>{if(!editor.dirty)unfocus();});
  window.addEventListener('vision:workspace-refresh',()=>{editor.dirty=false;project=null;unfocus();});
  window.addEventListener('beforeunload',event=>{if(editor.dirty){event.preventDefault();event.returnValue='';}});
  function mark(status){editor.dirty=true;status.textContent='Unsaved edits';}
  async function manager(){
    const data=await api('projects'),layer=el('div','vision-modal-layer'),dialog=el('section','vision-dialog workspace-dialog');dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');
    dialog.append(el('h2','','Workspaces'));const tools=el('div','workspace-manager-tools');
    let closing=false;const close=async()=>{if(closing)return;closing=true;await VisionShell.closeSheet(layer,'.workspace-dialog');layer.remove();};
    button('+ New workspace',async()=>{const name=await VisionShell.modal('Create a workspace',{input:true,text:'Creates a folder in Vision’s local workspaces directory.',confirm:'Create'});if(!name)return;const item=await api('projects',{create:true,name});await close();await openProject(item);},tools);
    button('Open folder',async()=>{const path=window.VisionDesktop?.pickFolder?await VisionDesktop.pickFolder():await VisionShell.modal('Open folder',{input:true,text:'Enter the full folder path.',confirm:'Open'});if(path){const item=await api('projects',{path});await close();await openProject(item);}},tools);dialog.append(tools);
    const list=el('div','workspace-recent-list');for(const item of [...data.items].reverse()){const b=button(item.name,async()=>{await close();await openById(item.id);},list);b.append(el('small','',item.path));}if(!data.items.length)list.append(el('p','','No saved workspaces yet.'));dialog.append(list);
    const actions=el('div','dialog-actions');button('Close',close,actions);dialog.append(actions);layer.append(dialog);document.body.append(layer);layer.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();close();}if(event.key==='Tab'){const buttons=[...dialog.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});await VisionShell.openSheet(layer,'.workspace-dialog');tools.querySelector('button').focus();
  }
  async function openById(id){const data=await api('projects'),item=data.items.find(p=>p.id===id);if(!item)throw Error('This workspace is no longer saved.');await openProject(item);}
  async function openProject(item){if(!await editor.mayLeave())return;project=await api('projects',{path:item.path});treeRelative='';const file={id:'project-'+project.id,name:project.name,kind:'project',projectId:project.id};VisionUI.addArtifact(file,false);VisionUI.choosePreview(file.id);await VisionWorkspace.reloadShared();}
  let contextMenu=null;
  const closeContext=()=>{contextMenu?.remove();contextMenu=null;};
  document.addEventListener('pointerdown',event=>{if(contextMenu&&!contextMenu.contains(event.target))closeContext();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeContext();});
  async function properties(item){
    const data=await api('projects/'+project.id+'/operation',{action:'properties',relative:item.relative});
    const layer=el('div','vision-modal-layer'),dialog=el('section','vision-dialog workspace-properties');dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.append(el('h2','','Properties'));const details=el('dl','workspace-properties-list');for(const [name,value] of [['Name',data.name],['Location',data.location],['Size',data.size==null?'Folder':data.size.toLocaleString()+' bytes'],['Type',data.type],['Modified',new Date(data.modified*1000).toLocaleString()]])details.append(el('dt','',name),el('dd','',value));dialog.append(details);const actions=el('div','dialog-actions');let closing=false;const close=async()=>{if(closing)return;closing=true;await VisionShell.closeSheet(layer,'.workspace-properties');layer.remove();};const done=button('Close',close,actions);dialog.append(actions);layer.append(dialog);document.body.append(layer);layer.onkeydown=event=>{if(event.key==='Escape')close();if(event.key==='Tab'){event.preventDefault();done.focus();}};await VisionShell.openSheet(layer,'.workspace-properties');done.focus();
  }
  function fileMenu(event,item,host){
    event.preventDefault();event.stopPropagation();closeContext();const menu=el('div','workspace-context-menu');contextMenu=menu;menu.setAttribute('role','menu');menu.setAttribute('aria-label',item.name+' actions');
    const run=async(action,extra={})=>{const result=await api('projects/'+project.id+'/operation',{action,relative:item.relative,...extra});if(['copy','cut'].includes(action))clipboardReady=true;if(action==='paste')clipboardReady=result.clipboard_ready!==false;const wasActive=(result.closed||[]).includes(activeFile?.id);for(const id of result.closed||[])VisionUI.closePreview(id);for(const file of result.files||[])VisionUI.addArtifact(file,false);if(wasActive&&result.files?.length)await VisionWorkspace.selectFile(result.files[0],{edit:true});await tree(host);await VisionWorkspace.reloadShared();return result;};
    if(!item.folder){button('Open / Edit',async()=>{const file=await api('projects/'+project.id+'/open',{relative:item.relative});await VisionWorkspace.selectFile(file,{edit:true});},menu);button('Preview',async()=>{const file=await api('projects/'+project.id+'/open',{relative:item.relative});await VisionWorkspace.selectFile(file);},menu);}
    else button('Open folder',()=>{treeRelative=item.relative;return tree(host);},menu);
    button('Copy',()=>run('copy'),menu).disabled=!item.relative||item.relative==='.';button('Cut',async()=>{if(await editor.mayLeave())await run('cut');},menu).disabled=!item.relative||item.relative==='.';button('Paste',async()=>{if(await editor.mayLeave())await run('paste');},menu).disabled=!clipboardReady;
    button('Copy path',()=>VisionUI.copyText(project.path.replace(/[\\/]+$/,'')+'/'+item.relative),menu);
    button('Rename',async()=>{if(!await editor.mayLeave())return;const name=await VisionShell.modal('Rename '+item.name,{input:true,value:item.name,confirm:'Rename'});if(name&&name!==item.name){await run('rename',{name});}},menu);
    button('Move to Recycle Bin',async()=>{if(!await editor.mayLeave())return;if(await VisionShell.modal('Recycle '+item.name+'?',{text:'Windows will move this item to the Recycle Bin.',confirm:'Move to Recycle Bin',danger:true}))await run('recycle');},menu);
    button('Properties',()=>properties(item),menu);
    for(const b of menu.querySelectorAll('button')){const handler=b.onclick;b.setAttribute('role','menuitem');b.onclick=event=>{closeContext();handler(event);};}
    document.body.append(menu);menu.style.left=Math.max(8,Math.min(event.clientX,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(8,Math.min(event.clientY,innerHeight-menu.offsetHeight-8))+'px';menu.querySelector('button')?.focus();
    menu.onkeydown=event=>{if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();const buttons=[...menu.querySelectorAll('button:not(:disabled)')],index=buttons.indexOf(document.activeElement);buttons[(index+(event.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus();}};
  }
  async function importFiles(files){
    if(!project)throw Error('Open a workspace folder before importing files.');
    const applications=/\.(exe|com|msi|msix|msixbundle|appx|appxbundle|dll|sys|scr|cpl|lnk|app|apk|dmg|pkg|deb|rpm|appimage|jar)$/i;let count=0;
    for(const file of files){if(applications.test(file.name))throw Error('Applications belong in Apps. Drop documents or source files into the editing workspace.');let path='';try{path=window.VisionDesktop?.filePath(file)||'';}catch{}let imported;if(path){const result=await api('projects/'+project.id+'/import-local',{relative:treeRelative,paths:[path]});imported=result.files;}else{const form=new FormData();form.append('file',file);const response=await fetch('/api/projects/'+project.id+'/import?relative='+encodeURIComponent(treeRelative),{method:'POST',body:form}),result=await response.json();if(!response.ok)throw Error(result.detail||'This file could not be imported.');imported=[result];}for(const item of imported)VisionUI.addArtifact(item,false);count++;}
    if(treeHost?.isConnected)await tree(treeHost);await VisionWorkspace.reloadShared();VisionWorkspace.notify({message:'Imported '+count+' '+(count===1?'file.':'files.'),success:true});
  }
  async function tree(host){
    const data=await api('projects/'+project.id+'/tree?relative='+encodeURIComponent(treeRelative));if(!host.isConnected)return;host.replaceChildren();const controls=el('div','workspace-tree-tools');
    const up=button('',()=>{const current=treeRelative.replace(/\\/g,'/');treeRelative=current.includes('/')?current.slice(0,current.lastIndexOf('/')):'';return tree(host);},controls);up.classList.add('workspace-parent-button');up.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 11 7-7 7 7M12 4v16"/></svg><span>Parent</span>';up.title='Go to parent folder';up.setAttribute('aria-label',up.title);up.disabled=!treeRelative||treeRelative==='.';
    button('+ Folder',async()=>{const name=await VisionShell.modal('New folder',{input:true,confirm:'Create'});if(name){await api('projects/'+project.id+'/folder',{relative:(treeRelative?treeRelative+'/':'')+name});await tree(host);}},controls);
    button('+ File',async()=>{const name=await VisionShell.modal('New file',{input:true,confirm:'Create'});if(name){const file=await api('projects/'+project.id+'/file',{relative:(treeRelative?treeRelative+'/':'')+name});await VisionWorkspace.selectFile(file,{edit:true});}},controls);host.append(controls,el('div','workspace-tree-path',project.name+(treeRelative&&treeRelative!=='.'?' / '+treeRelative:'')));
    for(const item of data.items){const n=button((item.folder?'▸ ':'')+item.name,async()=>{if(item.folder){treeRelative=item.relative;await tree(host);}else{const file=await api('projects/'+project.id+'/open',{relative:item.relative});await VisionWorkspace.selectFile(file,{edit:true});}},host);n.classList.add('workspace-tree-entry');n.title=item.name;n.oncontextmenu=event=>fileMenu(event,item,host);}
    host.oncontextmenu=event=>{if(event.target.closest('.workspace-tree-entry,.workspace-tree-tools'))return;fileMenu(event,{relative:treeRelative,name:project.name,folder:true},host);};
    const drag=event=>{if(![...event.dataTransfer.types].includes('Files'))return;event.preventDefault();event.stopPropagation();const overlay=document.querySelector('.workspace-drop-overlay');if(overlay)overlay.hidden=true;host.classList.add('workspace-tree-dropping');};host.ondragenter=drag;host.ondragover=drag;host.ondragleave=event=>{if(!host.contains(event.relatedTarget))host.classList.remove('workspace-tree-dropping');};host.ondrop=event=>{event.preventDefault();event.stopPropagation();host.classList.remove('workspace-tree-dropping');importFiles([...event.dataTransfer.files]).catch(fail);};
    if(data.truncated)host.append(el('small','','Showing the first 500 entries.'));
  }
  function shell(target,title){target._workspaceToken=Symbol('editor');target.replaceChildren();target.className='workspace-file-view workspace-edit-view';const host=el('div','workspace-editor-shell'),side=el('aside','workspace-file-tree'),body=el('section','workspace-editor-body'),bar=el('div','workspace-editor-toolbar');bar.append(el('strong','workspace-editor-title',title));const status=el('span','workspace-editor-state','');bar.append(status);body.append(bar);host.append(side,body);target.append(host);treeHost=side;if(project)tree(side).catch(fail);else side.hidden=true;
    if(project&&window.VisionDesktop?.openEditor){const workbench=button('VS Code workbench',async()=>{if(!await editor.mayLeave())return;const result=await VisionDesktop.openEditor(project.id);await VisionAppSurfaces.open(result);focus();},bar);workbench.classList.add('workspace-workbench-button');workbench.title='Open the complete installed VS Code editor for this workspace';}button('Done',leaveEdit,bar);focus();return {body,bar,status};}
  function renderProject(file,target){if(!project||project.id!==file.projectId){api('projects').then(data=>{if(VisionUI.currentPreview().id!==file.id)return;project=data.items.find(p=>p.id===file.projectId);if(project)renderProject(file,target);}).catch(fail);return;}const {body}=shell(target,project.name);body.append(el('div','workspace-editor-empty','Select a file to edit.'));}
  async function editFile(file){
    if(!await editor.mayLeave())return;
    if(file.kind!=='project'){project=await api('projects',{file_id:file.id,workspace_id:project?.id});await VisionWorkspace.reloadShared();}
    activeFile=file;const version=++editorVersion,target=$('#artifact-view');target.hidden=false;const {body,bar,status}=shell(target,file.name);const extension=file.name.split('.').pop().toLowerCase();
    if(extension==='pdf'){await pdfEditor(file,body,bar,status,version);return;}
    if(window.VisionDocumentEditors?.supports(file)){await VisionDocumentEditors.open(file,{body,bar,status,version,alive:()=>version===editorVersion,mark:()=>mark(status),saved:()=>{editor.dirty=false;}});return;}
    const loading=el('p','workspace-editor-loading','Opening editor…');body.append(loading);
    try{let data=await api('edit/'+file.id);if(version!==editorVersion)return;loading.remove();const area=el('textarea','workspace-code-editor');area.spellcheck=false;area.setAttribute('aria-label','Edit '+file.name);area.value=data.text;const newline=data.text.includes('\r\n')?'\r\n':'\n';area.oninput=()=>mark(status);area.addEventListener('keydown',event=>{if(event.key==='Tab'){event.preventDefault();const start=area.selectionStart,end=area.selectionEnd;area.setRangeText('  ',start,end,'end');mark(status);}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();save.click();}});body.append(area);
      const save=button('Save',async()=>{save.disabled=true;try{const result=await api('edit/'+file.id,{text:newline==='\r\n'?area.value.replace(/\r?\n/g,'\r\n'):area.value,revision:data.revision});data=result;editor.dirty=false;status.textContent='Saved';VisionUI.addArtifact(result.file,false);}finally{save.disabled=false;}},bar);
      button('Reload',async()=>{if(await editor.mayLeave())await editFile(file);},bar);
      if(['html','htm'].includes(extension)){
        const split=el('div','workspace-source-split'),source=el('div','workspace-source-pane'),preview=el('section','workspace-source-preview'),rail=el('button','workspace-source-divider');source.append(area);preview.hidden=rail.hidden=true;rail.type='button';rail.setAttribute('role','separator');rail.setAttribute('aria-orientation','vertical');rail.setAttribute('aria-label','Resize editor preview');const previewBar=el('div','workspace-sheet-tools'),frame=el('iframe','workspace-code-live');frame.title='HTML preview';frame.setAttribute('sandbox','allow-scripts');preview.append(previewBar,frame);split.append(source,rail,preview);body.append(split);
        const refresh=()=>{if(file.preview_url){const doc=new DOMParser().parseFromString(area.value,'text/html'),base=document.createElement('base');base.href=new URL('.',new URL(file.preview_url,location.href)).href;doc.head.prepend(base);frame.srcdoc='<!doctype html>'+doc.documentElement.outerHTML;}else frame.srcdoc=area.value;};button('Refresh preview',refresh,previewBar);button('Close',()=>{preview.hidden=rail.hidden=true;split.classList.remove('preview-open');frame.removeAttribute('srcdoc');},previewBar);button('Preview edits',()=>{preview.hidden=rail.hidden=false;split.classList.add('preview-open');refresh();},bar);
        rail.setAttribute('aria-valuemin','20');rail.setAttribute('aria-valuemax','80');rail.setAttribute('aria-valuenow','45');const resize=x=>{const bounds=split.getBoundingClientRect();const percent=Math.max(20,Math.min(80,(bounds.right-x)/Math.max(1,bounds.width)*100));split.style.setProperty('--source-preview-width',percent+'%');rail.setAttribute('aria-valuenow',String(Math.round(percent)));};rail.onpointerdown=event=>{rail.setPointerCapture(event.pointerId);document.body.classList.add('resizing');};rail.onpointermove=event=>{if(rail.hasPointerCapture(event.pointerId))resize(event.clientX);};rail.onlostpointercapture=()=>document.body.classList.remove('resizing');rail.onpointerup=()=>document.body.classList.remove('resizing');rail.onkeydown=event=>{if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const bounds=rail.getBoundingClientRect();resize(bounds.left+(event.key==='ArrowRight'?20:-20));}};
      }
    }catch(error){if(version!==editorVersion)return;loading.remove();body.append(el('p','workspace-editor-loading',error.message));button('Preview',()=>{unfocus();VisionUI.choosePreview(file.id);},bar);}
  }
  async function pdfEditor(file,body,bar,status,version){
    const info=await api('pdf/'+file.id);if(version!==editorVersion)return;const notes=[],rotations={},layout=el('div','workspace-pdf-layout'),frame=el('div','workspace-pdf-editor-page'),tools=el('aside','workspace-document-tools');layout.append(frame,tools);body.append(layout);const viewer=await VisionPDFViewer.create(file,frame,info);
    tools.append(el('h3','','PDF tools'),el('p','','Add notes and rotate pages. Save creates a new PDF and keeps the original.'));
    const pages=el('select');pages.setAttribute('aria-label','PDF page');info.pages.forEach((p,i)=>pages.append(new Option('Page '+(i+1),i)));tools.append(pages);pages.onchange=()=>viewer.go(Number(pages.value));frame.addEventListener('vision:pdf-page',event=>{pages.value=String(event.detail.page);pages.dispatchEvent(new Event('vision:selection-sync'));viewer.rotate(rotations[pages.value]||0);});
    const rotation=el('span','workspace-preview-note','No rotation');tools.append(rotation);button('Rotate page 90°',()=>{const page=pages.value;rotations[page]=((rotations[page]||0)+90)%360;viewer.rotate(rotations[page]);rotation.textContent='Page '+(Number(page)+1)+': '+rotations[page]+'° rotation pending';mark(status);},tools);
    const note=el('textarea','workspace-note-input');note.placeholder='Write a page note';note.setAttribute('aria-label','PDF note');note.oninput=()=>mark(status);tools.append(note);const list=el('div','workspace-note-list');tools.append(list);
    button('Add note',()=>{if(!note.value.trim())return;const item={page:Number(pages.value),text:note.value.trim(),slot:notes.length};notes.push(item);note.value='';const row=el('div','workspace-pdf-note');row.append(el('span','','Page '+(item.page+1)+': '+item.text));button('×',()=>{notes.splice(notes.indexOf(item),1);row.remove();mark(status);},row);list.append(row);mark(status);},tools);
    const save=button('Save edited copy',async()=>{if(note.value.trim())throw Error('Click Add note to include the note before saving.');save.disabled=true;try{const result=await api('pdf/'+file.id,{revision:info.revision,notes,rotations});editor.dirty=false;await VisionWorkspace.selectFile(result,{edit:true});}finally{save.disabled=false;}},bar);
  }
  window.VisionProjects={manager,openById,openProject,editFile,renderProject,leaveEdit,importFiles,enterEdit:focus};
})();
